JS='''(()=>{'use strict';const data=JSON.parse(document.getElementById('foundry-data').textContent),$=id=>document.getElementById(id),Core=globalThis.SutiWorldFoundry;const codes=Object.keys(data.editions);const norm=x=>{x=String(x||'').toLowerCase();if(x==='es-419')x='es';return codes.includes(x)?x:'ru'};let lang=norm(new URLSearchParams(location.search).get('lang')),blueprint=null;const themes=['day','night','contrast'];const make=(t,x)=>{const n=document.createElement(t);if(x!==undefined)n.textContent=x;return n};const save=(k,v)=>{try{localStorage.setItem(k,v)}catch{}};try{if(!new URLSearchParams(location.search).has('lang'))lang=norm(localStorage.getItem('suti-locale'));const t=localStorage.getItem('suti-theme');if(themes.includes(t))document.documentElement.dataset.theme=t}catch{}const labels=()=>data.editions[lang],common=()=>data.common[lang].ui;const names={ru:'Русский',en:'English',es:'Español','pt-br':'Português brasileiro','zh-hans':'简体中文',hi:'हिन्दी',fr:'Français',ar:'العربية',bn:'বাংলা',eo:'Esperanto',sa:'संस्कृतम्',la:'Latina',yzh:'язэхъ · RU'};for(const c of codes){const o=make('option',names[c]);o.value=c;$('language').append(o)}function preview(){if(!blueprint)return;const svg=$('preview');svg.replaceChildren();const ns='http://www.w3.org/2000/svg';const title=document.createElementNS(ns,'title');title.id='preview-title';title.textContent=blueprint.title;svg.append(title);const scale=260/blueprint.width;for(const o of blueprint.objects){if(!o.module_id)continue;const x=210+o.position[0]*scale,y=160+o.position[2]*scale;const rect=document.createElementNS(ns,'rect');rect.setAttribute('x',String(x-23));rect.setAttribute('y',String(y-23));rect.setAttribute('width','46');rect.setAttribute('height','46');rect.setAttribute('rx','6');svg.append(rect);const text=document.createElementNS(ns,'text');text.setAttribute('x',String(x));text.setAttribute('y',String(y+4));text.textContent=o.module_id.split('.')[1];svg.append(text)}$('rooms').replaceChildren();for(const o of blueprint.objects.filter(x=>x.module_id)){const m=data.modules[lang].find(m=>m.id===o.module_id);$('rooms').append(make('li',m.title+' · '+m.function))}$('code').textContent=JSON.stringify(blueprint,null,2)+'\\n\\n'+Core.roblox(blueprint)+'\\n'+Core.minecraft(blueprint)}function render(){const c=labels(),a=common(),e=data.common[lang];document.documentElement.lang=e.contentLanguage;document.documentElement.dir=e.direction;document.title=c.title+' · SUTI.world';document.querySelectorAll('[data-copy]').forEach(n=>n.textContent=c[n.dataset.copy]);$('language-label').textContent=a.language;$('theme-label').textContent=a.theme;$('local-note').textContent=a.localOnly;$('review-note').textContent=lang==='yzh'?a.sourcefallback:a.reviewPending;const old=$('layout').value;$('layout').replaceChildren();for(const id of ['garden','temple','island']){const o=make('option',c[id]);o.value=id;$('layout').append(o)}$('layout').value=old||'garden';$('theme').replaceChildren();for(const [i,key]of ['light','dark','focus'].entries()){const o=make('option',a[key]+(i===2?' · CONTRAST':''));o.value=themes[i];$('theme').append(o)}$('theme').value=document.documentElement.dataset.theme||'day';$('language').value=lang;for(const id of ['back','return']){$(id).href='world-atlas.html?lang='+lang;$('return').textContent=a.return}const u=new URL(location.href);u.searchParams.set('lang',lang);try{history.replaceState(null,'',u)}catch{}preview()}function download(text,name,type){const u=URL.createObjectURL(new Blob([text],{type})),a=make('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}$('world-form').addEventListener('submit',event=>{event.preventDefault();try{blueprint=Core.create({title:$('world-name').value,seed:$('seed').value,layout:$('layout').value,size:$('size').value});preview();for(const id of ['json','roblox','minecraft'])$(id).disabled=false;$('status').textContent=common().local+' · '+blueprint.objects.length+' · '+common().source}catch(e){$('status').textContent=common().unavailable+' · '+e.message}});$('json').addEventListener('click',()=>{if(blueprint)download(JSON.stringify(blueprint,null,2),'SUTI-world-'+blueprint.seed+'.json','application/json')});$('roblox').addEventListener('click',()=>{if(blueprint)download(Core.roblox(blueprint),'SUTI-world-'+blueprint.seed+'.lua','text/plain')});$('minecraft').addEventListener('click',()=>{if(blueprint)download(Core.minecraft(blueprint),'SUTI-world-'+blueprint.seed+'.mcfunction','text/plain')});$('language').addEventListener('change',()=>{lang=norm($('language').value);save('suti-locale',lang);render()});$('theme').addEventListener('change',()=>{document.documentElement.dataset.theme=$('theme').value;save('suti-theme',$('theme').value)});render()})();'''
def outputs():
 if any(len(v)!=len(FIELDS) for v in WORDS.values()):raise ValueError('Incomplete foundry edition')
 editions={c:dict(zip(FIELDS,words)) for c,words in WORDS.items()}
 common={c:json.loads((ROOT/'locales/world-atlas'/(c+'.json')).read_text()) for c in WORDS}
 modules={c:json.loads((ROOT/'shared/care-veche/locales'/(c+'.json')).read_text())['modules'] for c in WORDS}
 data={'editions':editions,'common':common,'modules':modules}
 css=(ROOT/'assets/css/suti-angels-editorial.css').read_text().replace('../fonts/','https://ezargaruna.github.io/suticore/assets/fonts/')+'\n'+(ROOT/'assets/css/world-atlas.css').read_text()
 core=(ROOT/'assets/js/world-foundry-core.js').read_text()
 html=HTML.replace('@@CSS@@',css).replace('@@DATA@@',json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')).replace('@@CORE@@',core).replace('@@JS@@',JS)
 out={'world-foundry.html':html}
 for c,e in editions.items():out['locales/world-foundry/'+c+'.json']=json.dumps(e,ensure_ascii=False,indent=2)+'\n'
 out['locales/world-foundry/coverage.json']=json.dumps({'schema':'suti.world-foundry.coverage.v1','source_locale':'ru','source_sha256':hashlib.sha256(json.dumps(editions['ru'],ensure_ascii=False,indent=2).encode()+b'\n').hexdigest(),'routes':{c:{'fields':len(FIELDS),'status':'Russian-gloss-HOLD' if c=='yzh' else 'editorial-draft-native-review-pending','engine_acceptance':'NOT_TESTED'} for c in WORDS},'generator':'local deterministic geometry prototype','platform_gateway':'NOT_IMPLEMENTED','official_references':['https://create.roblox.com/docs/parts','https://learn.microsoft.com/en-us/minecraft/creator/documents/functionsintroduction?view=minecraft-bedrock-stable'],'privacy':'page-memory only; no network or text persistence'},ensure_ascii=False,indent=2)+'\n'
 return out
def main():
 p=argparse.ArgumentParser();p.add_argument('--check',action='store_true');a=p.parse_args()
 for rel,text in outputs().items():
  path=ROOT/rel
  if a.check:
   if not path.exists() or path.read_text()!=text:raise SystemExit('Stale '+rel)
  else:path.parent.mkdir(parents=True,exist_ok=True);path.write_text(text)
 print('World foundry: 13 UI routes; deterministic local geometry and code sketches; engine acceptance NOT_TESTED')
if __name__=='__main__':main()
